export const ComputerController = () => {
  // NOTE: Generated by codex... Justification: Did not want to manually write every index and could not think of a faster way to generate the possibleIndexes.
  const possibleIndexes = Array.from({ length: 100 }, (_, index) => [
    Math.floor(index / 10),
    index % 10,
  ]);

  const attackRandomCoordinate = (enemyBoard) => {
    const length = possibleIndexes.length;
    const randomIndex = Math.floor(Math.random() * length);
    const randomCoordinate = possibleIndexes[randomIndex];

    possibleIndexes.splice(randomIndex, 1);

    return enemyBoard.receiveAttack(randomCoordinate);
  };

  return {
    attackRandomCoordinate,
    get possibleIndexesLength() {
      return possibleIndexes.length;
    },
  };
};
